<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/session.php';requireAdmin();$em=['Happy','Calm','Sad','Angry','Anxious','Lonely','Fearful','Hurt','Disappointed','Frustrated','Confused','Tired','Stressed','Overwhelmed','Neutral'];$sit=['Friends / Friendship','Relationship / Love','Family Problems','College / Studies','Work / Career','Financial Problems','Social Pressure','Breakup / Loss','Loneliness','Conflict / Anger','Self Confidence','Time Management','Sleep Problems','Social Media','General Stress'];$msg='';if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM recommendation_rules WHERE id=?');$s->bind_param('i',$id);$s->execute();$msg='Deleted.';}if($_SERVER['REQUEST_METHOD']==='POST'){$e=$_POST['emotion'];$si=$_POST['situation'];$mn=(int)$_POST['min'];$mx=(int)$_POST['max'];$t=trim($_POST['title']);$d=trim($_POST['description']);$ac=trim($_POST['activity']);$ca=trim($_POST['category']);$p=(int)$_POST['priority'];$s=$conn->prepare('INSERT INTO recommendation_rules(emotion,situation,min_stress,max_stress,title,description,activity,category,priority) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('ssiissssi',$e,$si,$mn,$mx,$t,$d,$ac,$ca,$p);$s->execute();$msg='Recommendation added.';}$r=$conn->query('SELECT * FROM recommendation_rules ORDER BY situation,emotion,priority DESC,id');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recommendations</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="navbar"><a class="logo" href="dashboard.php"><div class="logo-icon">🌿</div><span>Stress<span>Care</span></span></a><div class="nav-links"><a class="nav-btn" href="dashboard.php">Dashboard</a><a class="nav-btn" href="logout.php">Logout</a></div></header><main class="container"><div class="title"><h2>Manage Recommendations</h2><p>Add emotion and situation based rules.</p></div><?php if($msg):?><div class="alert success"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="card"><form method="post"><div class="grid2"><div class="form-group"><label>Emotion</label><select name="emotion"><?php foreach($em as $x):?><option><?=htmlspecialchars($x)?></option><?php endforeach;?></select></div><div class="form-group"><label>Situation</label><select name="situation"><?php foreach($sit as $x):?><option><?=htmlspecialchars($x)?></option><?php endforeach;?></select></div><div class="form-group"><label>Min Stress</label><input type="number" name="min" value="1" min="1" max="10"></div><div class="form-group"><label>Max Stress</label><input type="number" name="max" value="10" min="1" max="10"></div><div class="form-group"><label>Title</label><input name="title" required></div><div class="form-group"><label>Category</label><input name="category" value="Wellness" required></div></div><div class="form-group"><label>Description</label><textarea name="description" required></textarea></div><div class="form-group"><label>Activity</label><textarea name="activity"></textarea></div><div class="form-group"><label>Priority</label><input type="number" name="priority" value="1" min="1"></div><button class="btn">Add Recommendation</button></form></div><div class="card" style="margin-top:20px"><div class="table-wrap"><table><tr><th>Emotion</th><th>Situation</th><th>Stress</th><th>Title</th><th>Category</th><th></th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($x['emotion'])?></td><td><?=htmlspecialchars($x['situation'])?></td><td><?=$x['min_stress']?>-<?=$x['max_stress']?></td><td><?=htmlspecialchars($x['title'])?></td><td><?=htmlspecialchars($x['category'])?></td><td><a class="btn btn-secondary" href="?delete=<?=$x['id']?>" onclick="return confirm('Delete this recommendation?')">Delete</a></td></tr><?php endwhile;?></table></div></div></main></body></html>
